export interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface TodoInputProps {
  onAddTodo: (text: string) => void;
}

export interface TodoItemProps {
  todo: TodoItem;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

export interface TodoFilterProps {
  currentFilter: FilterType;
  onFilterChange: (filter: FilterType) => void;
  totalCount: number;
  activeCount: number;
  completedCount: number;
  onClearCompleted: () => void;
}

import { useState, type FormEvent, type ChangeEvent } from 'react';
import type { TodoInputProps } from '../types';

const TodoInput = ({ onAddTodo }: TodoInputProps) => {
  const [inputText, setInputText] = useState('');

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) {
      return;
    }
    onAddTodo?.(trimmed);
    setInputText('');
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
  };

  return (
    <form className="todo-input-form" onSubmit={handleSubmit}>
      <input
        type="text"
        className="todo-input"
        placeholder="新しいやること・タスクを入力..."
        value={inputText}
        onChange={handleChange}
        maxLength={100}
      />
      <button type="submit" className="btn btn-primary">
        追加
      </button>
    </form>
  );
};

export default TodoInput;

import type { ChangeEvent } from 'react';
import type { TodoItemProps } from '../types';

const TodoItem = ({ todo, onToggle, onDelete }: TodoItemProps) => {
  const handleCheckboxChange = (_e: ChangeEvent<HTMLInputElement>) => {
    onToggle?.(todo.id);
  };

  const handleDeleteClick = () => {
    onDelete?.(todo.id);
  };

  const itemClassName = todo.completed ? 'todo-item completed' : 'todo-item';

  return (
    <li className={itemClassName}>
      <label className="todo-label">
        <input
          type="checkbox"
          className="todo-checkbox"
          checked={todo.completed}
          onChange={handleCheckboxChange}
        />
        <span className="todo-text">{todo.text}</span>
      </label>
      <span className="todo-date">{todo.createdAt}</span>
      <button
        type="button"
        className="todo-delete-btn"
        onClick={handleDeleteClick}
        aria-label={`${todo.text}を削除`}
      >
        削除
      </button>
    </li>
  );
};

export default TodoItem;

import { useState } from 'react';
import type { TodoItem as TodoItemType, FilterType } from './types';
import TodoInput from './components/TodoInput';
import TodoItem from './components/TodoItem';

const INITIAL_TODOS: TodoItemType[] = [
  {
    id: '1',
    text: '牛乳と卵をスーパーで買い出し',
    completed: false,
    createdAt: '2025/01/15 09:30',
  },
  {
    id: '2',
    text: '週報レポートの提出と確認',
    completed: false,
    createdAt: '2025/01/15 10:15',
  },
  {
    id: '3',
    text: '部屋の掃除とゴミ出し',
    completed: false,
    createdAt: '2025/01/15 11:00',
  },
  {
    id: '4',
    text: '朝のストレッチ15分',
    completed: true,
    createdAt: '2025/01/15 07:00',
  },
];

const App = () => {
  const [todos, setTodos] = useState<TodoItemType[]>(INITIAL_TODOS);
  const [filter, setFilter] = useState<FilterType>('all');

  const handleAddTodo = (text: string) => {
    const now = new Date();
    const formattedDate = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const newTodo: TodoItemType = {
      id: `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      text,
      completed: false,
      createdAt: formattedDate,
    };
    setTodos((prevTodos) => [newTodo, ...prevTodos]);
  };

  const handleToggleTodo = (id: string) => {
    setTodos((prevTodos) =>
      prevTodos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== id));
  };

  const handleClearCompleted = () => {
    setTodos((prevTodos) => prevTodos.filter((todo) => !todo.completed));
  };

  const totalCount = todos.length;
  const activeCount = todos.filter((todo) => !todo.completed).length;
  const completedCount = totalCount - activeCount;

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') {
      return !todo.completed;
    }
    if (filter === 'completed') {
      return todo.completed;
    }
    return true;
  });

  return (
    <div className="todo-app">
      <main className="todo-card">
        <header className="todo-header">
          <h1 className="todo-title">やることリスト</h1>
          <p className="todo-subtitle">今日のタスクを整理して、すっきり効率的に進めましょう</p>
        </header>

        <TodoInput onAddTodo={handleAddTodo} />

        <div className="todo-filters">
          <div className="filter-group">
            <button
              type="button"
              className={filter === 'all' ? 'btn-filter active' : 'btn-filter'}
              onClick={() => setFilter('all')}
            >
              すべて ({totalCount})
            </button>
            <button
              type="button"
              className={filter === 'active' ? 'btn-filter active' : 'btn-filter'}
              onClick={() => setFilter('active')}
            >
              未完了 ({activeCount})
            </button>
            <button
              type="button"
              className={filter === 'completed' ? 'btn-filter active' : 'btn-filter'}
              onClick={() => setFilter('completed')}
            >
              完了済み ({completedCount})
            </button>
          </div>
        </div>

        {filteredTodos.length > 0 ? (
          <ul className="todo-list">
            {filteredTodos.map((todo) => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onToggle={handleToggleTodo}
                onDelete={handleDeleteTodo}
              />
            ))}
          </ul>
        ) : (
          <div className="empty-state">
            {filter === 'completed'
              ? '完了したタスクはまだありません。'
              : filter === 'active'
              ? '未完了のタスクはありません！素晴らしいです。'
              : '登録されているやることがありません。上のフォームから追加してください。'}
          </div>
        )}

        <footer className="todo-footer">
          <span className="todo-count">
            残り <strong>{activeCount}</strong> 件の未完了タスク
          </span>
          {completedCount > 0 && (
            <button
              type="button"
              className="btn btn-danger"
              onClick={handleClearCompleted}
            >
              完了済みを一括削除
            </button>
          )}
        </footer>
      </main>
    </div>
  );
};

export default App;
